(()=>{const key='frame-project-view-state-v1';let states={};try{states=JSON.parse(localStorage.getItem(key)||'{}');}catch{}let active='',restoring=false;const id=()=>String(data.project_id||data.local_id||data.title||'');function store(){if(restoring||typeof diskReady!=='undefined'&&!diskReady||!active||active!==id())return;const shot=data.shots?.[si],character=data.characters?.[ci],scene=typeof sceneIndex!=='undefined'?data.scenes?.[sceneIndex]:null;states[active]={tab,tabName:tabs[tab],shotId:shot?.shot_id||shot?.id,si,characterId:character?.id||character?.character_id,ci,sceneId:scene?.id||scene?.scene_id,sceneIndex:typeof sceneIndex!=='undefined'?sceneIndex:0,sub:typeof selectedSubShot!=='undefined'?selectedSubShot:0,shotMode:typeof shotMode!=='undefined'?shotMode:'shots',clipIndex:typeof clipIndex!=='undefined'?clipIndex:0,scrollY:window.scrollY,mainTop:document.querySelector('main')?.scrollTop||0};try{localStorage.setItem(key,JSON.stringify(states));}catch{}}
function indexBy(items,savedId,fallback){const n=(items||[]).findIndex(item=>savedId&&(item.id===savedId||item.character_id===savedId||item.scene_id===savedId||item.shot_id===savedId));return n>=0?n:Math.max(0,Math.min(Number(fallback)||0,Math.max(0,(items?.length||0)-1)));}
const prior=render;render=function(){let restored;const ready=typeof diskReady==='undefined'||diskReady;if(ready&&active!==id()){active=id();restored=states[active];if(restored){restoring=true;const named=restored.tabName?tabs.indexOf(restored.tabName):-1;tab=named>=0?named:Number.isInteger(restored.tab)&&restored.tab>=0&&restored.tab<tabs.length?restored.tab:0;si=indexBy(data.shots,restored.shotId,restored.si);ci=indexBy(data.characters,restored.characterId,restored.ci);if(typeof sceneIndex!=='undefined')sceneIndex=indexBy(data.scenes,restored.sceneId,restored.sceneIndex);if(typeof selectedSubShot!=='undefined')selectedSubShot=Math.max(0,Math.min(restored.sub||0,(data.shots?.[si]?.sub_shots?.length||1)-1));if(typeof shotMode!=='undefined')shotMode=restored.shotMode==='clips'?'clips':'shots';if(typeof clipIndex!=='undefined')clipIndex=indexBy(data.shotScript?.generation_clips,null,restored.clipIndex);}}prior();if(restored){requestAnimationFrame(()=>requestAnimationFrame(()=>{window.scrollTo(0,restored.scrollY||0);const main=document.querySelector('main');if(main)main.scrollTop=restored.mainTop||0;restoring=false;store();}));}else store();};let scrollTimer;document.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(store,150);},true);window.addEventListener('pagehide',store);window.addEventListener('beforeunload',store);document.addEventListener('visibilitychange',()=>{if(document.hidden)store();});render();})();
